#include <iostream>

struct Point {
    int x;
    int y;
    Point& operator+=(const Point& other) {
        x += other.x;
        y += other.y;
        return *this;
    }
};

int main() {
    Point a{1, 2};
    a += Point{3, 4};
    std::cout << a.x << " " << a.y << "\n";
    return 0;
}

#include <iostream>

class Counter {
public:
    Counter& operator++() { ++value; return *this; }
    Counter operator++(int) { Counter old = *this; ++value; return old; }
    int get() const { return value; }
private:
    int value = 0;
};

int main() {
    Counter c;
    c++;
    std::cout << c.get() << "\n";
    return 0;
}

#include <iostream>

class Box {
public:
    explicit Box(int v) : value(v) {}
    friend int read(const Box& b);
private:
    int value;
};

int read(const Box& b) { return b.value; }

int main() {
    Box b(5);
    std::cout << read(b) << "\n";
    return 0;
}

