#include <fstream>
#include <iostream>
#include <string>

int main() {
    {
        std::ofstream out("log.txt");
        out << "one\n";
    }
    {
        std::ofstream out("log.txt", std::ios::app);
        out << "two\n";
    }
    std::ifstream in("log.txt");
    std::string line;
    int lines = 0;
    while (std::getline(in, line)) ++lines;
    std::cout << lines << "\n";
    return 0;
}

#include <fstream>
